--
-- Table structure for table `verified_answer_attempts`
--

CREATE TABLE `verified_answer_attempts` (
  `attempt_id` bigint(20) UNSIGNED NOT NULL,
  `battle_id` char(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `question_token` char(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `question_code` varchar(60) NOT NULL,
  `question_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`question_json`)),
  `answer_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`answer_json`)),
  `is_correct` tinyint(1) NOT NULL,
  `timed_out` tinyint(1) NOT NULL,
  `elapsed_ms` int(10) UNSIGNED NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

