INSERT INTO `verified_answer_attempts` (`attempt_id`, `battle_id`, `question_token`, `question_code`, `question_json`, `answer_json`, `is_correct`, `timed_out`, `elapsed_ms`, `created_at`) VALUES
(1, 'df7e396c43bf4a4dbceca53d40b351cd', 'fec3f8f685a9a058784b9edf12d924e2', 'camp-sentence-006', '{\"id\":\"camp-sentence-006\",\"realm\":\"camp\",\"type\":\"SENTENCE_BUILDER\",\"skill\":\"sentenceConstruction\",\"difficulty\":\"MEDIUM\",\"question\":\"Build the correct sentence.\",\"questionZh\":\"把单词排列成正确的句子。\",\"words\":[\"The\",\"our\",\"lights\",\"lantern\",\"path\"],\"answerOrder\":[\"The\",\"lantern\",\"lights\",\"our\",\"path\"],\"prompt\":\"Start with \\\"The lantern\\\". Use every word once.\",\"promptZh\":\"意思是“灯笼照亮我们的道路”。以 The lantern 开头，每个单词用一次。\",\"explanation\":\"Lights is a verb meaning gives light to. The singular subject the lantern takes lights.\",\"explanationZh\":\"Lights 在这里是动词，表示照亮；单数主语 the lantern 搭配 lights。\",\"timeLimit\":12,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":false}', '[\"The\",\"lights\",\"path\",\"our\",\"lantern\"]', 0, 0, 7283, '2026-10-15 02:58:37'),
(2, 'df7e396c43bf4a4dbceca53d40b351cd', 'b6520200d9924a5468f8f8426ed47c59', 'camp-tf-001', '{\"id\":\"camp-tf-001\",\"realm\":\"camp\",\"type\":\"TRUE_FALSE\",\"skill\":\"vocabulary\",\"difficulty\":\"MEDIUM\",\"question\":\"To \\\"borrow\\\" something is to use it for a while and then return it.\",\"answer\":true,\"explanation\":\"Borrow means use something temporarily and give it back.\",\"questionZh\":\"“Borrow”是暂时使用某物，然后归还。\",\"explanationZh\":\"Borrow 表示借用，使用一段时间后归还。\",\"timeLimit\":10,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":false}', 'true', 1, 0, 1320, '2026-10-15 02:58:40'),
(3, 'df7e396c43bf4a4dbceca53d40b351cd', '4bb22ba60072513927037970f37520af', 'camp-tf-005', '{\"id\":\"camp-tf-005\",\"realm\":\"camp\",\"type\":\"TRUE_FALSE\",\"skill\":\"vocabulary\",\"difficulty\":\"MEDIUM\",\"question\":\"\\\"We should help each other\\\" gives advice.\",\"answer\":true,\"explanation\":\"Should is used here to give advice. Each other means one another.\",\"questionZh\":\"“We should help each other”表达建议。\",\"explanationZh\":\"Should 在这里表示建议；each other 表示彼此。整句是“我们应该互相帮助”。\",\"timeLimit\":10,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":false}', 'true', 1, 0, 421, '2026-10-15 02:58:42'),
(4, 'df7e396c43bf4a4dbceca53d40b351cd', '42923dd1d3d8d4639a9969fee6acce3e', 'camp-tf-009', '{\"id\":\"camp-tf-009\",\"realm\":\"camp\",\"type\":\"TRUE_FALSE\",\"skill\":\"grammar\",\"difficulty\":\"MEDIUM\",\"question\":\"After \\\"must\\\", use the base form: \\\"You must carry water\\\".\",\"answer\":true,\"explanation\":\"A modal verb such as must is followed by the base form of the verb, here carry.\",\"questionZh\":\"“Must”后用动词原形，例如“You must carry water”。\",\"explanationZh\":\"Must 等情态动词后用动词原形，这里使用 carry（携带）。\",\"timeLimit\":10,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":false}', 'true', 1, 0, 235, '2026-10-15 02:58:43'),
(5, 'df7e396c43bf4a4dbceca53d40b351cd', '2f4fa4bdaf2fd48570c3680c0c1bff01', 'camp-sentence-005', '{\"id\":\"camp-sentence-005\",\"realm\":\"camp\",\"type\":\"SENTENCE_BUILDER\",\"skill\":\"sentenceConstruction\",\"difficulty\":\"MEDIUM\",\"question\":\"Build the correct sentence.\",\"questionZh\":\"把单词排列成正确的句子。\",\"words\":[\"signs\",\"read\",\"They\",\"these\",\"can\"],\"answerOrder\":[\"They\",\"can\",\"read\",\"these\",\"signs\"],\"prompt\":\"Start with \\\"They\\\". Use every word once.\",\"promptZh\":\"意思是“他们能读懂这些路牌”。以 They 开头，每个单词用一次。\",\"explanation\":\"Use can + the base verb read. These signs is plural.\",\"explanationZh\":\"Can 后接动词原形 read；these signs（这些路牌）是复数。\",\"timeLimit\":12,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":false}', '[\"They\",\"can\",\"read\",\"these\",\"signs\"]', 1, 0, 11604, '2026-10-15 02:58:55'),
(6, 'e213e8e8b7c54b72a0088cedc0ebbe38', 'ae1d37ebbae9272444a360c57b7389e6', 'camp-tf-003', '{\"id\":\"camp-tf-003\",\"realm\":\"camp\",\"type\":\"TRUE_FALSE\",\"skill\":\"vocabulary\",\"difficulty\":\"MEDIUM\",\"question\":\"A \\\"shelter\\\" is a place that protects people from bad weather.\",\"answer\":true,\"explanation\":\"A shelter can provide protection from rain, wind or other bad weather.\",\"questionZh\":\"“Shelter”是能让人躲避恶劣天气的地方。\",\"explanationZh\":\"Shelter 表示庇护处，可以让人躲避雨、风等恶劣天气。\",\"timeLimit\":10,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":true}', 'true', 1, 0, 889, '2026-10-15 02:59:12'),
(7, 'e213e8e8b7c54b72a0088cedc0ebbe38', 'd04e0ff55b78b55ff5175b32a1539451', 'camp-tf-008', '{\"id\":\"camp-tf-008\",\"realm\":\"camp\",\"type\":\"TRUE_FALSE\",\"skill\":\"vocabulary\",\"difficulty\":\"MEDIUM\",\"question\":\"\\\"Supplies\\\" can mean food and equipment needed for a trip.\",\"answer\":true,\"explanation\":\"Supplies are things needed for an activity, such as food and equipment for a trip.\",\"questionZh\":\"“Supplies”可以指旅途中需要的食物和装备。\",\"explanationZh\":\"Supplies 表示活动所需的物资，例如旅行需要的食物和装备。\",\"timeLimit\":10,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":true}', 'true', 1, 0, 172, '2026-10-15 02:59:13'),
(8, 'e213e8e8b7c54b72a0088cedc0ebbe38', '6e2b658ef73a4f3c3990e02be2473f4f', 'camp-sentence-010', '{\"id\":\"camp-sentence-010\",\"realm\":\"camp\",\"type\":\"SENTENCE_BUILDER\",\"skill\":\"sentenceConstruction\",\"difficulty\":\"MEDIUM\",\"question\":\"Build the correct sentence.\",\"questionZh\":\"把单词排列成正确的句子。\",\"words\":[\"us\",\"warm\",\"campfire\",\"The\",\"keeps\"],\"answerOrder\":[\"The\",\"campfire\",\"keeps\",\"us\",\"warm\"],\"prompt\":\"Start with \\\"The campfire\\\". Use every word once.\",\"promptZh\":\"意思是“篝火让我们保持温暖”。以 The campfire 开头，每个单词用一次。\",\"explanation\":\"Use keeps + object us + adjective warm. Warm describes how we feel.\",\"explanationZh\":\"Keeps 后接宾语 us 和形容词 warm；warm 描述我们的状态。\",\"timeLimit\":12,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":true}', '[\"The\",\"campfire\",\"keeps\",\"us\",\"warm\"]', 1, 0, 10950, '2026-10-15 02:59:25'),
(9, 'e213e8e8b7c54b72a0088cedc0ebbe38', 'e1682b68af8d5dc8b29a1f82a40ea4d7', 'camp-tf-006', '{\"id\":\"camp-tf-006\",\"realm\":\"camp\",\"type\":\"TRUE_FALSE\",\"skill\":\"vocabulary\",\"difficulty\":\"MEDIUM\",\"question\":\"\\\"Behind the tent\\\" means in front of the tent.\",\"answer\":false,\"explanation\":\"Behind means at the back of something. In front of means before its front.\",\"questionZh\":\"“Behind the tent”的意思是在帐篷前面。\",\"explanationZh\":\"Behind 表示在后面；in front of 表示在前面。\",\"timeLimit\":10,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":true}', 'true', 0, 0, 1506, '2026-10-15 02:59:28'),
(10, 'e213e8e8b7c54b72a0088cedc0ebbe38', '14724b58e8cfcacc72d8fac3bbec2f3c', 'camp-tf-002', '{\"id\":\"camp-tf-002\",\"realm\":\"camp\",\"type\":\"TRUE_FALSE\",\"skill\":\"vocabulary\",\"difficulty\":\"MEDIUM\",\"question\":\"\\\"Left\\\" and \\\"right\\\" describe the same direction.\",\"answer\":false,\"explanation\":\"Left and right are different directions.\",\"questionZh\":\"“Left”和“right”表示相同方向。\",\"explanationZh\":\"Left（左）和 right（右）表示不同方向。\",\"timeLimit\":10,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":true}', 'true', 0, 0, 501, '2026-10-15 02:59:30'),
(11, 'e213e8e8b7c54b72a0088cedc0ebbe38', '846988bb632c74d86d92cd28746a1cf4', 'camp-tf-010', '{\"id\":\"camp-tf-010\",\"realm\":\"camp\",\"type\":\"TRUE_FALSE\",\"skill\":\"vocabulary\",\"difficulty\":\"MEDIUM\",\"question\":\"\\\"Across the bridge\\\" means staying on the same side without crossing.\",\"answer\":false,\"explanation\":\"Across the bridge means going from one end of the bridge to the other.\",\"questionZh\":\"“Across the bridge”的意思是留在原处，不走过桥。\",\"explanationZh\":\"Across the bridge 表示从桥的一端走到另一端，也就是过桥。\",\"timeLimit\":10,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":true}', 'false', 1, 0, 602, '2026-10-15 02:59:32'),
(12, 'e213e8e8b7c54b72a0088cedc0ebbe38', 'ba81e6388265d7cdbf27cd36fe515feb', 'camp-sentence-002', '{\"id\":\"camp-sentence-002\",\"realm\":\"camp\",\"type\":\"SENTENCE_BUILDER\",\"skill\":\"sentenceConstruction\",\"difficulty\":\"MEDIUM\",\"question\":\"Build the correct sentence.\",\"questionZh\":\"把单词排列成正确的句子。\",\"words\":[\"supplies\",\"should\",\"share\",\"our\",\"We\"],\"answerOrder\":[\"We\",\"should\",\"share\",\"our\",\"supplies\"],\"prompt\":\"Start with \\\"We\\\". Use every word once.\",\"promptZh\":\"意思是“我们应该分享物资”。以 We 开头，每个单词用一次。\",\"explanation\":\"Use should + the base verb share. Our supplies tells us what to share.\",\"explanationZh\":\"Should 后接动词原形 share；our supplies 表示要分享的物资。\",\"timeLimit\":12,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":true}', '[\"We\",\"should\",\"share\",\"our\",\"supplies\"]', 1, 0, 6686, '2026-10-15 02:59:39'),
(13, '24c25400279149adbc4f2121c0a61c19', '27a2ec38190f894b00082f24a17a242c', 'ruins-tf-008', '{\"id\":\"ruins-tf-008\",\"realm\":\"ruins\",\"type\":\"TRUE_FALSE\",\"skill\":\"itEnglish\",\"difficulty\":\"MEDIUM\",\"question\":\"\\\"Access denied\\\" means you have permission to enter.\",\"answer\":false,\"explanation\":\"Access denied means permission has not been granted.\",\"questionZh\":\"“Access denied”表示你获得了进入权限。\",\"explanationZh\":\"Access denied 表示拒绝访问，也就是没有获得权限。\",\"timeLimit\":10,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":false}', 'true', 0, 0, 742, '2026-10-15 03:00:10'),
(14, '24c25400279149adbc4f2121c0a61c19', 'f2e8a1df24fb294b45f3cd4a4223c3d5', 'ruins-tf-010', '{\"id\":\"ruins-tf-010\",\"realm\":\"ruins\",\"type\":\"TRUE_FALSE\",\"skill\":\"itEnglish\",\"difficulty\":\"MEDIUM\",\"question\":\"A \\\"username\\\" and a \\\"password\\\" always mean the same thing.\",\"answer\":false,\"explanation\":\"A username identifies an account. A password is a secret used to help verify access.\",\"questionZh\":\"“Username”和“password”的意思总是相同的。\",\"explanationZh\":\"Username（用户名）用于识别账号；password（密码）是帮助验证访问权限的秘密信息。\",\"timeLimit\":10,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":false}', 'false', 1, 0, 125, '2026-10-15 03:00:12'),
(15, '24c25400279149adbc4f2121c0a61c19', '1d74257a24b5f566ad233ed06c0c76c5', 'ruins-sentence-004', '{\"id\":\"ruins-sentence-004\",\"realm\":\"ruins\",\"type\":\"SENTENCE_BUILDER\",\"skill\":\"itEnglish\",\"difficulty\":\"MEDIUM\",\"question\":\"Build the correct sentence.\",\"questionZh\":\"把单词排列成正确的句子。\",\"words\":[\"our\",\"The\",\"stores\",\"records\",\"database\"],\"answerOrder\":[\"The\",\"database\",\"stores\",\"our\",\"records\"],\"prompt\":\"Start with \\\"The database\\\". Use every word once.\",\"promptZh\":\"意思是“数据库保存我们的记录”。以 The database 开头，每个单词用一次。\",\"explanation\":\"The database is singular, so use stores. Records means stored information.\",\"explanationZh\":\"The database 是单数主语，因此用 stores；records 表示保存的记录或信息。\",\"timeLimit\":12,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":false}', '[\"The\",\"database\",\"stores\",\"our\",\"records\"]', 1, 0, 17779, '2026-10-15 03:00:31'),
(16, '24c25400279149adbc4f2121c0a61c19', '3aa6f51ad826adedaa5bb98ac3955f1f', 'ruins-sentence-006', '{\"id\":\"ruins-sentence-006\",\"realm\":\"ruins\",\"type\":\"SENTENCE_BUILDER\",\"skill\":\"itEnglish\",\"difficulty\":\"MEDIUM\",\"question\":\"Build the correct sentence.\",\"questionZh\":\"把单词排列成正确的句子。\",\"words\":[\"sends\",\"The\",\"a\",\"server\",\"message\"],\"answerOrder\":[\"The\",\"server\",\"sends\",\"a\",\"message\"],\"prompt\":\"Start with \\\"The server\\\". Use every word once.\",\"promptZh\":\"意思是“服务器发送一条消息”。以 The server 开头，每个单词用一次。\",\"explanation\":\"The singular subject the server takes sends. A message is the object.\",\"explanationZh\":\"单数主语 the server 搭配 sends；a message 是宾语。\",\"timeLimit\":12,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":false}', '[\"The\",\"server\",\"sends\",\"a\",\"message\"]', 1, 0, 7626, '2026-10-15 03:00:39'),
(17, '24c25400279149adbc4f2121c0a61c19', '298554c5577f3499f4b48f2926ac7b17', 'ruins-tf-002', '{\"id\":\"ruins-tf-002\",\"realm\":\"ruins\",\"type\":\"TRUE_FALSE\",\"skill\":\"itEnglish\",\"difficulty\":\"MEDIUM\",\"question\":\"A \\\"password\\\" should be shared with every stranger.\",\"answer\":false,\"explanation\":\"A password is private information used to prove identity. Do not share it with strangers.\",\"questionZh\":\"“Password”应该分享给每一个陌生人。\",\"explanationZh\":\"Password（密码）是用于验证身份的私人信息，不应分享给陌生人。\",\"timeLimit\":10,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":false}', 'true', 0, 0, 917, '2026-10-15 03:00:41'),
(18, '24c25400279149adbc4f2121c0a61c19', 'd127c483a8fa8201e656a2f37d899a66', 'ruins-sentence-003', '{\"id\":\"ruins-sentence-003\",\"realm\":\"ruins\",\"type\":\"SENTENCE_BUILDER\",\"skill\":\"itEnglish\",\"difficulty\":\"MEDIUM\",\"question\":\"Build the correct sentence.\",\"questionZh\":\"把单词排列成正确的句子。\",\"words\":[\"We\",\"can\",\"open\",\"file\",\"this\"],\"answerOrder\":[\"We\",\"can\",\"open\",\"this\",\"file\"],\"prompt\":\"Start with \\\"We\\\". Use every word once.\",\"promptZh\":\"意思是“我们可以打开这个文件”。以 We 开头，每个单词用一次。\",\"explanation\":\"Use can + the base verb open. This file is the object.\",\"explanationZh\":\"Can 后接动词原形 open；this file 是宾语。\",\"timeLimit\":12,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":false}', '[\"We\",\"can\",\"open\",\"this\",\"file\"]', 1, 0, 5415, '2026-10-15 03:00:48'),
(19, 'c9b66a878c344f21951964141fb69012', '15aee0daeb367953671f3b77b0f4e1bd', 'ruins-tf-004', '{\"id\":\"ruins-tf-004\",\"realm\":\"ruins\",\"type\":\"TRUE_FALSE\",\"skill\":\"itEnglish\",\"difficulty\":\"MEDIUM\",\"question\":\"\\\"Download\\\" means delete a file from a server.\",\"answer\":false,\"explanation\":\"Download means receive a file from another computer or server. It does not mean delete.\",\"questionZh\":\"“Download”的意思是从服务器删除文件。\",\"explanationZh\":\"Download 表示下载，从另一台电脑或服务器接收文件，并不是删除文件。\",\"timeLimit\":10,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":true}', 'true', 0, 0, 879, '2026-10-15 03:00:59'),
(20, 'c9b66a878c344f21951964141fb69012', '29716f555b13459ef503d864e36613f7', 'ruins-sentence-008', '{\"id\":\"ruins-sentence-008\",\"realm\":\"ruins\",\"type\":\"SENTENCE_BUILDER\",\"skill\":\"itEnglish\",\"difficulty\":\"MEDIUM\",\"question\":\"Build the correct sentence.\",\"questionZh\":\"把单词排列成正确的句子。\",\"words\":[\"network\",\"devices\",\"Our\",\"connects\",\"these\"],\"answerOrder\":[\"Our\",\"network\",\"connects\",\"these\",\"devices\"],\"prompt\":\"Start with \\\"Our network\\\". Use every word once.\",\"promptZh\":\"意思是“我们的网络连接这些设备”。以 Our network 开头，每个单词用一次。\",\"explanation\":\"The singular subject our network takes connects. These devices is a plural object.\",\"explanationZh\":\"单数主语 our network 搭配 connects；these devices（这些设备）是复数宾语。\",\"timeLimit\":12,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":true}', '[\"Our\",\"devices\",\"connects\",\"these\",\"network\"]', 0, 0, 4718, '2026-10-15 03:01:05'),
(21, 'c9b66a878c344f21951964141fb69012', 'fc262c5b04aac776a4a0eec557661915', 'ruins-tf-007', '{\"id\":\"ruins-tf-007\",\"realm\":\"ruins\",\"type\":\"TRUE_FALSE\",\"skill\":\"itEnglish\",\"difficulty\":\"MEDIUM\",\"question\":\"A \\\"connection\\\" can link two computer systems.\",\"answer\":true,\"explanation\":\"A connection is a link that can let systems communicate.\",\"questionZh\":\"“Connection”可以连接两个电脑系统。\",\"explanationZh\":\"Connection 表示连接，可以让系统相互通信。\",\"timeLimit\":10,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":true}', 'true', 1, 0, 1130, '2026-10-15 03:01:08'),
