(48, '78b4dd8e3f8a40baa72b22f1836e34e7', 'ce09b8c97da1d192df7397a9bd83d6a2', 'camp-tf-010', '{\"id\":\"camp-tf-010\",\"realm\":\"camp\",\"type\":\"TRUE_FALSE\",\"skill\":\"vocabulary\",\"difficulty\":\"MEDIUM\",\"question\":\"\\\"Across the bridge\\\" means staying on the same side without crossing.\",\"answer\":false,\"explanation\":\"Across the bridge means going from one end of the bridge to the other.\",\"questionZh\":\"“Across the bridge”的意思是留在原处，不走过桥。\",\"explanationZh\":\"Across the bridge 表示从桥的一端走到另一端，也就是过桥。\",\"timeLimit\":10,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":false}', 'true', 0, 0, 953, '2026-10-15 04:38:01'),
