(50, '78b4dd8e3f8a40baa72b22f1836e34e7', '8fa5ecc2825a46a1d5baec6fc756b593', 'camp-tf-001', '{\"id\":\"camp-tf-001\",\"realm\":\"camp\",\"type\":\"TRUE_FALSE\",\"skill\":\"vocabulary\",\"difficulty\":\"MEDIUM\",\"question\":\"To \\\"borrow\\\" something is to use it for a while and then return it.\",\"answer\":true,\"explanation\":\"Borrow means use something temporarily and give it back.\",\"questionZh\":\"“Borrow”是暂时使用某物，然后归还。\",\"explanationZh\":\"Borrow 表示借用，使用一段时间后归还。\",\"timeLimit\":10,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":false}', 'false', 0, 0, 883, '2026-10-15 04:38:09'),
(51, '78b4dd8e3f8a40baa72b22f1836e34e7', '21a235a19f8538858cb6414de50a9572', 'camp-tf-008', '{\"id\":\"camp-tf-008\",\"realm\":\"camp\",\"type\":\"TRUE_FALSE\",\"skill\":\"vocabulary\",\"difficulty\":\"MEDIUM\",\"question\":\"\\\"Supplies\\\" can mean food and equipment needed for a trip.\",\"answer\":true,\"explanation\":\"Supplies are things needed for an activity, such as food and equipment for a trip.\",\"questionZh\":\"“Supplies”可以指旅途中需要的食物和装备。\",\"explanationZh\":\"Supplies 表示活动所需的物资，例如旅行需要的食物和装备。\",\"timeLimit\":10,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":false}', 'true', 1, 0, 526, '2026-10-15 04:38:11'),
