(70, '1a2aae4db39146f1a530087376d51c73', 'bd366a7c0e4a8e6970eceb1e09860973', 'ruins-sentence-009', '{\"id\":\"ruins-sentence-009\",\"realm\":\"ruins\",\"type\":\"SENTENCE_BUILDER\",\"skill\":\"itEnglish\",\"difficulty\":\"MEDIUM\",\"question\":\"Build the correct sentence.\",\"questionZh\":\"把单词排列成正确的句子。\",\"words\":[\"the\",\"have\",\"saved\",\"document\",\"We\"],\"answerOrder\":[\"We\",\"have\",\"saved\",\"the\",\"document\"],\"prompt\":\"Start with \\\"We\\\". Use every word once.\",\"promptZh\":\"意思是“我们已经保存文档”。以 We 开头，每个单词用一次。\",\"explanation\":\"The present perfect uses have + the past participle saved. The document is the object.\",\"explanationZh\":\"现在完成时使用 have + 过去分词 saved；the document 是宾语。\",\"timeLimit\":12,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":false}', '[\"We\",\"have\",\"saved\",\"the\",\"document\"]', 1, 0, 11513, '2026-10-17 04:06:21'),
