(73, '4ddf8e3786724cd3ac0a04a499166eb3', 'ee565cd3fd4dd27e9401abd3f82a0606', 'ruins-sentence-005', '{\"id\":\"ruins-sentence-005\",\"realm\":\"ruins\",\"type\":\"SENTENCE_BUILDER\",\"skill\":\"itEnglish\",\"difficulty\":\"MEDIUM\",\"question\":\"Build the correct sentence.\",\"questionZh\":\"把单词排列成正确的句子。\",\"words\":[\"This\",\"the\",\"unlocks\",\"key\",\"gate\"],\"answerOrder\":[\"This\",\"key\",\"unlocks\",\"the\",\"gate\"],\"prompt\":\"Start with \\\"This key\\\". Use every word once.\",\"promptZh\":\"意思是“这把钥匙打开大门”。以 This key 开头，每个单词用一次。\",\"explanation\":\"The singular subject this key takes unlocks. The gate is the object.\",\"explanationZh\":\"单数主语 this key 搭配 unlocks；the gate（大门）是宾语。\",\"timeLimit\":12,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":false}', '[\"This\",\"key\",\"unlocks\",\"the\",\"gate\"]', 1, 0, 4526, '2026-10-17 04:07:02'),
(74, '4ddf8e3786724cd3ac0a04a499166eb3', '2e85392e520970dad351447d3a47b726', 'ruins-tf-009', '{\"id\":\"ruins-tf-009\",\"realm\":\"ruins\",\"type\":\"TRUE_FALSE\",\"skill\":\"itEnglish\",\"difficulty\":\"MEDIUM\",\"question\":\"\\\"The system is ready\\\" says the system can be used.\",\"answer\":true,\"explanation\":\"Ready means prepared for use or action.\",\"questionZh\":\"“The system is ready”表示系统已准备好，可以使用。\",\"explanationZh\":\"Ready 表示已经准备好，可以使用或开始行动。\",\"timeLimit\":10,\"xp\":15,\"coins\":8,\"englishPower\":2,\"timed\":false}', 'true', 1, 0, 1231, '2026-10-17 04:07:04'),
