(142, '6da5e8fec945411393f343f9df15f7e1', 'e24d2f20a629d1241f4b15072fd568bf', 'ruins-tf-023', '{\"id\":\"ruins-tf-023\",\"realm\":\"ruins\",\"type\":\"TRUE_FALSE\",\"skill\":\"itEnglish\",\"question\":\"The requests are being processed describes an ongoing passive action.\",\"questionZh\":\"The requests are being processed 描述正在进行的被动动作。\",\"answer\":true,\"explanation\":\"Are being plus processed forms the present-continuous passive.\",\"explanationZh\":\"Are being 加 processed 构成现在进行时的被动语态。\",\"difficulty\":\"HARD\",\"timeLimit\":16,\"xp\":20,\"coins\":10,\"englishPower\":3,\"timed\":false}', 'true', 1, 0, 943, '2026-10-18 08:06:50'),
(143, '6da5e8fec945411393f343f9df15f7e1', '260ff3fc477aa90cbf52950af9d41950', 'ruins-tf-016', '{\"id\":\"ruins-tf-016\",\"realm\":\"ruins\",\"type\":\"TRUE_FALSE\",\"skill\":\"itEnglish\",\"question\":\"The warning may have failed states with certainty that a failure occurred.\",\"questionZh\":\"The warning may have failed 肯定地说明故障已经发生。\",\"answer\":false,\"explanation\":\"May have expresses possibility, not certainty.\",\"explanationZh\":\"May have 表示可能发生过，而非确定。\",\"difficulty\":\"HARD\",\"timeLimit\":16,\"xp\":20,\"coins\":10,\"englishPower\":3,\"timed\":false}', 'false', 1, 0, 1095, '2026-10-18 08:06:52'),
(144, '6da5e8fec945411393f343f9df15f7e1', '5c82e55e5e1fbf847cee78b1d546f704', 'ruins-sentence-028', '{\"id\":\"ruins-sentence-028\",\"realm\":\"ruins\",\"type\":\"SENTENCE_BUILDER\",\"skill\":\"itEnglish\",\"question\":\"Build the correct sentence.\",\"questionZh\":\"把单词排列成正确的句子。\",\"words\":[\"take\",\"will\",\"restarted\",\"has\",\"service\",\"changes\",\"effect\",\"until\",\"every\",\"No\"],\"answerOrder\":[\"No\",\"changes\",\"will\",\"take\",\"effect\",\"until\",\"every\",\"service\",\"has\",\"restarted\"],\"prompt\":\"Start with \\\"No changes\\\". Use every word once; keep the stated meaning.\",\"promptZh\":\"意思是“每个服务都重新启动之后，更改才会生效”。以 No changes 开头，每个词用一次。\",\"explanation\":\"No plus until postpones the effect until the stated event is complete.\",\"explanationZh\":\"No 加 until 表示必须等到指定事件完成后才会生效。\",\"difficulty\":\"HARD\",\"timeLimit\":24,\"xp\":20,\"coins\":10,\"englishPower\":3,\"timed\":false}', '[\"No\",\"changes\",\"every\",\"effect\",\"until\",\"has\",\"service\",\"restarted\",\"take\",\"will\"]', 0, 0, 26528, '2026-10-18 08:07:20'),
