(169, '8d53aa9b22a94f5fb8e776482db6a374', '411135b0636b607e98eb1068106e4992', 'ruins-tf-021', '{\"id\":\"ruins-tf-021\",\"realm\":\"ruins\",\"type\":\"TRUE_FALSE\",\"skill\":\"itEnglish\",\"question\":\"Obsolete software is described as outdated rather than newly introduced.\",\"questionZh\":\"Obsolete software 指过时的软件，而不是刚推出的软件。\",\"answer\":true,\"explanation\":\"Obsolete means no longer current or in common use.\",\"explanationZh\":\"Obsolete 表示过时或已不再通用。\",\"difficulty\":\"HARD\",\"timeLimit\":16,\"xp\":20,\"coins\":10,\"englishPower\":3,\"timed\":false}', 'true', 1, 0, 630, '2026-10-18 08:31:29'),
