(171, '8d53aa9b22a94f5fb8e776482db6a374', '34d695cef47c5985f3f3d82c1cafa345', 'ruins-sentence-024', '{\"id\":\"ruins-sentence-024\",\"realm\":\"ruins\",\"type\":\"SENTENCE_BUILDER\",\"skill\":\"itEnglish\",\"question\":\"Build the correct sentence.\",\"questionZh\":\"把单词排列成正确的句子。\",\"words\":[\"If\",\"had\",\"recovered\",\"have\",\"we\",\"sooner,\",\"could\",\"continued\",\"network\",\"the\"],\"answerOrder\":[\"If\",\"the\",\"network\",\"had\",\"recovered\",\"sooner,\",\"we\",\"could\",\"have\",\"continued\"],\"prompt\":\"Start with \\\"If the\\\". Use every word once; keep the stated meaning.\",\"promptZh\":\"意思是“如果网络更早恢复，我们本来就能够继续”。以 If the 开头，每个词用一次。\",\"explanation\":\"Past-perfect had recovered and could have continued describe an unreal past condition.\",\"explanationZh\":\"Had recovered 与 could have continued 表示与过去事实相反的假设。\",\"difficulty\":\"HARD\",\"timeLimit\":24,\"xp\":20,\"coins\":10,\"englishPower\":3,\"timed\":false}', '[\"If\",\"had\",\"recovered\",\"have\",\"we\",\"sooner,\",\"could\",\"continued\",\"network\",\"the\"]', 0, 0, 6007, '2026-10-18 08:32:01'),
(172, '8d53aa9b22a94f5fb8e776482db6a374', 'ead69dab38f09afa231dfe55a41be344', 'ruins-sentence-007', '{\"id\":\"ruins-sentence-007\",\"realm\":\"ruins\",\"type\":\"SENTENCE_BUILDER\",\"skill\":\"itEnglish\",\"question\":\"Build the correct sentence.\",\"questionZh\":\"把单词排列成正确的句子。\",\"words\":[\"before\",\"enter\",\"authentication\",\"begin\",\"You\",\"can\",\"must\",\"your\",\"username\"],\"answerOrder\":[\"You\",\"must\",\"enter\",\"your\",\"username\",\"before\",\"authentication\",\"can\",\"begin\"],\"prompt\":\"Start with \\\"You must\\\". Use every word once; keep the stated meaning.\",\"promptZh\":\"意思是“你必须先输入用户名，验证才能开始”。以 You must 开头，每个词用一次。\",\"explanation\":\"Before orders the two actions; must takes the base verb enter.\",\"explanationZh\":\"Before 规定动作顺序；must 后接动词原形 enter。\",\"difficulty\":\"HARD\",\"timeLimit\":24,\"xp\":20,\"coins\":10,\"englishPower\":3,\"timed\":false}', '[\"You\",\"must\",\"enter\",\"your\",\"username\",\"before\",\"authentication\",\"can\",\"begin\"]', 1, 0, 17008, '2026-10-18 08:32:19'),
(173, '8d53aa9b22a94f5fb8e776482db6a374', '7d5079f57dd86cdd7ce63b74288898d4', 'ruins-sentence-020', '{\"id\":\"ruins-sentence-020\",\"realm\":\"ruins\",\"type\":\"SENTENCE_BUILDER\",\"skill\":\"itEnglish\",\"question\":\"Build the correct sentence.\",\"questionZh\":\"把单词排列成正确的句子。\",\"words\":[\"will\",\"access\",\"restore\",\"valid\",\"credentials\",\"We\",\"your\",\"remain\",\"that\",\"provided\"],\"answerOrder\":[\"We\",\"will\",\"restore\",\"access\",\"provided\",\"that\",\"your\",\"credentials\",\"remain\",\"valid\"],\"prompt\":\"Start with \\\"We will\\\". Use every word once; keep the stated meaning.\",\"promptZh\":\"意思是“只要你的凭据仍有效，我们就会恢复访问”。以 We will 开头，每个词用一次。\",\"explanation\":\"Provided that states a condition; credentials is plural and takes remain.\",\"explanationZh\":\"Provided that 表示条件；复数 credentials 搭配 remain。\",\"difficulty\":\"HARD\",\"timeLimit\":24,\"xp\":20,\"coins\":10,\"englishPower\":3,\"timed\":false}', '[\"We\",\"remain\",\"credentials\",\"valid\",\"restore\",\"access\",\"will\",\"your\",\"that\",\"provided\"]', 0, 0, 8026, '2026-10-18 08:32:28'),
(174, '8d53aa9b22a94f5fb8e776482db6a374', '5efc650c96dc2f3797c05fdc378ddac1', 'ruins-sentence-025', '{\"id\":\"ruins-sentence-025\",\"realm\":\"ruins\",\"type\":\"SENTENCE_BUILDER\",\"skill\":\"itEnglish\",\"question\":\"Build the correct sentence.\",\"questionZh\":\"把单词排列成正确的句子。\",\"words\":[\"continued\",\"repeated\",\"Despite\",\"some\",\"sharing\",\"private\",\"credentials\",\"their\",\"users\",\"warnings,\"],\"answerOrder\":[\"Despite\",\"repeated\",\"warnings,\",\"some\",\"users\",\"continued\",\"sharing\",\"their\",\"private\",\"credentials\"],\"prompt\":\"Start with \\\"Despite repeated\\\". Use every word once; keep the stated meaning.\",\"promptZh\":\"意思是“尽管多次收到警告，一些用户仍继续分享私人凭据”。以 Despite repeated 开头，每个词用一次。\",\"explanation\":\"Despite is followed by the noun phrase repeated warnings.\",\"explanationZh\":\"Despite 后接名词短语 repeated warnings。\",\"difficulty\":\"HARD\",\"timeLimit\":24,\"xp\":20,\"coins\":10,\"englishPower\":3,\"timed\":false}', '[\"Despite\",\"sharing\",\"private\",\"credentials\",\"their\",\"users\",\"warnings,\",\"some\",\"repeated\",\"continued\"]', 0, 0, 9392, '2026-10-18 08:32:39'),
(175, '8d53aa9b22a94f5fb8e776482db6a374', 'fe1308be31b2d25b9ce27eedf646ce44', 'ruins-tf-016', '{\"id\":\"ruins-tf-016\",\"realm\":\"ruins\",\"type\":\"TRUE_FALSE\",\"skill\":\"itEnglish\",\"question\":\"The warning may have failed states with certainty that a failure occurred.\",\"questionZh\":\"The warning may have failed 肯定地说明故障已经发生。\",\"answer\":false,\"explanation\":\"May have expresses possibility, not certainty.\",\"explanationZh\":\"May have 表示可能发生过，而非确定。\",\"difficulty\":\"HARD\",\"timeLimit\":16,\"xp\":20,\"coins\":10,\"englishPower\":3,\"timed\":false}', 'false', 1, 0, 4506, '2026-10-18 08:32:45'),
(176, '07a46355718543a9a18310c082c252f6', '8ced7d9f784f02eafcb4ad0a9c4619c5', 'ruins-tf-003', '{\"id\":\"ruins-tf-003\",\"realm\":\"ruins\",\"type\":\"TRUE_FALSE\",\"skill\":\"itEnglish\",\"question\":\"The notice upload complete indicates that sending the file has finished.\",\"questionZh\":\"Upload complete 这个通知表示发送文件的操作已经结束。\",\"answer\":true,\"explanation\":\"Complete marks a finished action; upload sends a file to another system.\",\"explanationZh\":\"Complete 表示完成；upload 指向另一个系统上传文件。\",\"difficulty\":\"HARD\",\"timeLimit\":16,\"xp\":20,\"coins\":10,\"englishPower\":3,\"timed\":false}', 'true', 1, 0, 1309, '2026-10-18 08:33:10'),
(177, '07a46355718543a9a18310c082c252f6', '584f3fd31e14fb83e721396d86e66cd4', 'ruins-tf-014', '{\"id\":\"ruins-tf-014\",\"realm\":\"ruins\",\"type\":\"TRUE_FALSE\",\"skill\":\"itEnglish\",\"question\":\"In the file was restored by Mira, the file performed the restoration.\",\"questionZh\":\"在 the file was restored by Mira 中，是文件执行了恢复操作。\",\"answer\":false,\"explanation\":\"The file receives the action; Mira is the agent after by.\",\"explanationZh\":\"文件是动作接受者，by 后的 Mira 才是执行者。\",\"difficulty\":\"HARD\",\"timeLimit\":16,\"xp\":20,\"coins\":10,\"englishPower\":3,\"timed\":false}', 'true', 0, 0, 667, '2026-10-18 08:33:11'),
(178, '07a46355718543a9a18310c082c252f6', 'd6e1b32f01930336aab8f44883d5eee8', 'ruins-tf-022', '{\"id\":\"ruins-tf-022\",\"realm\":\"ruins\",\"type\":\"TRUE_FALSE\",\"skill\":\"itEnglish\",\"question\":\"Retrieve a record means permanently destroy that record.\",\"questionZh\":\"Retrieve a record 的意思是永久销毁那条记录。\",\"answer\":false,\"explanation\":\"Retrieve means find and obtain something stored.\",\"explanationZh\":\"Retrieve 表示查找并取回已保存的内容。\",\"difficulty\":\"HARD\",\"timeLimit\":16,\"xp\":20,\"coins\":10,\"englishPower\":3,\"timed\":false}', 'true', 0, 0, 2533, '2026-10-18 08:33:15');

